import { mkdir, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

import { isProductionOrigin, resolveApiBaseUrl, resolveSiteOrigin } from './site-config.mjs';

const ENVIRONMENT_PATH = 'src/environments/environment.ts';

export function renderEnvironment({ apiBaseUrl, siteOrigin }) {
  return [
    '// Generated by tools/site-environment.mjs — edits are overwritten by the next build.',
    'export const environment = {',
    `  production: ${isProductionOrigin(siteOrigin)},`,
    `  apiBaseUrl: ${JSON.stringify(apiBaseUrl)},`,
    `  siteOrigin: ${JSON.stringify(siteOrigin)},`,
    '};',
    '',
  ].join('\n');
}

export async function writeEnvironment({ environmentPath, apiBaseUrl, siteOrigin }) {
  await mkdir(dirname(environmentPath), { recursive: true });
  await writeFile(environmentPath, renderEnvironment({ apiBaseUrl, siteOrigin }), 'utf8');
}

if (import.meta.main) {
  const apiBaseUrl = resolveApiBaseUrl();
  const siteOrigin = resolveSiteOrigin();

  try {
    await writeEnvironment({ environmentPath: ENVIRONMENT_PATH, apiBaseUrl, siteOrigin });
    console.log(`Wrote ${ENVIRONMENT_PATH}, addressing ${apiBaseUrl} from ${siteOrigin}`);
  } catch (failure) {
    console.error(failure.message);
    process.exitCode = 1;
  }
}
